const $=s=>document.querySelector(s),KEY='kelten-spurensuche-v2';
const autoCount=stations.flatMap(s=>s.tasks).filter(t=>t.type!=='write').length;
let state={station:0,task:0,results:{},answers:{},draft:''},storageOK=true,selection=[],order=[],activeCard=null,showResult=false;
try{const raw=localStorage.getItem(KEY);const saved=raw?JSON.parse(raw):null;if(saved&&typeof saved==='object'){state.station=Number.isInteger(saved.station)&&saved.station>=0&&saved.station<6?saved.station:0;state.task=Number.isInteger(saved.task)&&saved.task>=0&&saved.task<3?saved.task:0;state.draft=typeof saved.draft==='string'?saved.draft:'';for(const [k,v]of Object.entries(saved.results||{}))if(/^[0-5]-[0-2]$/.test(k)&&typeof v?.correct==='boolean')state.results[k]={correct:v.correct,first:v.first===true};for(const [k,v]of Object.entries(saved.answers||{}))if(/^[0-5]-[0-2]$/.test(k)&&Array.isArray(v)&&v.every(x=>typeof x==='string'||typeof x==='number'||x===null))state.answers[k]=v;}else{const old=JSON.parse(localStorage.getItem('kelten-spurensuche-v1'));if(typeof old?.draft==='string')state.draft=old.draft;}}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').replace(/ae/g,'a').replace(/oe/g,'o').replace(/ue/g,'u').replace(/[^a-z0-9]/g,'');}
const key=()=>`${state.station}-${state.task}`;
const current=()=>stations[state.station].tasks[state.task];
function loadAnswer(){selection=[...(state.answers[key()]||[])];const n=current().items?.length||0;order=current().type==='order'&&selection.length===n&&new Set(selection).size===n&&selection.every(v=>Number.isInteger(v)&&v>=0&&v<n)?[...selection]:Array.from({length:n},(_,i)=>i);activeCard=null;}
function remember(){state.answers[key()]=current().type==='order'?[...order]:[...selection];save();}
function start(s,t=0){state.station=s;state.task=t;showResult=false;loadAnswer();save();render();$('#game').focus({preventScroll:true});}
function sidebar(){const count=Object.values(state.results).filter(r=>r.correct).length,points=Object.values(state.results).filter(r=>r.first).length;
 $('#stations').innerHTML=stations.map((s,i)=>{const done=s.tasks.every((_,j)=>state.results[`${i}-${j}`]?.correct);return `<button class="station ${i===state.station&&!showResult?'active':''} ${done?'done':''}" data-station="${i}" ${i===state.station&&!showResult?'aria-current="step"':''}><span class="num">${done?'✓':String(i+1).padStart(2,'0')}</span>${s.title}</button>`;}).join('');
 document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>start(+b.dataset.station));$('#progressText').textContent=`${count} / 18 abgeschlossen`;$('#score').textContent=`${points} / ${autoCount} Ersttreffer`;$('#progress').value=count;
}
function render(){sidebar();if(showResult){renderResult();return;}const s=stations[state.station],t=current();
 const labels={text:'BEGRIFFE EINTRAGEN',write:'SCHREIBEN & SELBST PRÜFEN',number:'ZEITANKER',pairs:'PAARE VERBINDEN',sort:'KARTEN SORTIEREN',mark:'TEXT MARKIEREN',letters:'BUCHSTABENRÄTSEL',order:'REIHENFOLGE'};
 $('#game').innerHTML=`<section class="mission"><div class="eyebrow">STATION ${String(state.station+1).padStart(2,'0')} / 06 · ${s.tag}</div><h2>${s.title}</h2><p>${s.intro}</p></section>${s.video?`<section class="video-panel"><div class="video-actions"><a href="${SRF}" target="_blank" rel="noopener">SRF-Beitrag ansehen ↗</a><button id="loadVideo" class="quiet">Video hier laden</button></div><p>Gesamtlänge: ca. 12 Minuten. Für die Aufgaben: 02:08–02:31, 07:09–07:39 und 10:31–11:21.</p><p class="video-note">Beim Laden wird eine Verbindung zu SRF hergestellt. Ohne Video hilft dir die Wissenskarte unten.</p><div id="video"></div></section>`:''}<div class="pills" aria-label="Aufgabe wählen">${s.tasks.map((_,i)=>`<button class="pill ${i===state.task?'active':''} ${state.results[`${state.station}-${i}`]?.correct?'done':''}" data-task="${i}" ${i===state.task?'aria-current="step"':''}>${i+1}. Spur</button>`).join('')}</div><section class="card"><div class="taskmeta">${labels[t.type]} · AUFGABE ${state.station*3+state.task+1} / 18</div><h3>${t.q}</h3><div id="input"></div><div id="feedback" aria-live="polite"></div><div class="actions"><button id="check" class="primary">${t.type==='write'?'Mit Kriterien vergleichen':'Antwort prüfen'}</button><button id="next" class="quiet" ${state.results[key()]?.correct?'':'hidden'}>${state.task===2&&state.station===5?'Zur Auswertung':'Nächste Spur →'}</button></div><details><summary>Wissenskarte öffnen</summary><p>${s.note}</p><p class="source-line">${s.source}</p></details></section>${!storageOK?'<p class="storage-warning">Dein Browser erlaubt kein Speichern. Dein Fortschritt bleibt nur für diese Sitzung erhalten.</p>':''}`;
 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>start(state.station,+b.dataset.task));if(s.video)$('#loadVideo').onclick=()=>{$('#video').innerHTML='<iframe title="SRF: Die Kelten und die Römer" src="https://www.srf.ch/play/embed?urn=urn:srf:video:3da18acb-1a0a-4cab-97ce-0b0fb3f4f4e4" allow="fullscreen" allowfullscreen></iframe>';$('#loadVideo').disabled=true;};
 renderInput();$('#check').onclick=check;$('#next').onclick=next;
}
function changed(){remember();$('#feedback').innerHTML='';$('#check').disabled=false;if(current().type==='write'&&state.results[key()]?.correct){delete state.results[key()];save();sidebar();$('#next').hidden=true;document.querySelector(`[data-task="${state.task}"]`).classList.remove('done');}}
function renderInput(){const t=current(),el=$('#input');
 if(['text','number','write'].includes(t.type)){const fields=t.fields||t.prompts?.map(label=>({label}))||[{label:t.label}];el.innerHTML=fields.map((f,i)=>`<label class="entry-label" for="entry-${i}">${f.label}</label>${t.type==='write'?`<textarea id="entry-${i}" data-entry="${i}" placeholder="Formuliere in eigenen Worten …">${esc(selection[i]||'')}</textarea>`:`<input id="entry-${i}" class="entry" data-entry="${i}" type="${t.type==='number'?'number':'text'}" ${t.type==='number'?'min="1" max="3000" step="1"':''} autocomplete="off" value="${esc(selection[i]??'')}">`}`).join('')+(t.type==='write'?'<p class="small">Dein Text wird gespeichert. Du prüfst ihn selbst anhand konkreter Kriterien; es gibt keine automatische Benotung.</p>':'');document.querySelectorAll('[data-entry]').forEach(b=>b.oninput=()=>{selection[+b.dataset.entry]=b.value;changed();});}
 else if(t.type==='order'){el.innerHTML=`<p class="small">${t.instruction||'Verschiebe mit den Pfeil-Schaltflächen. Oben steht das älteste Ereignis.'}</p>`+order.map((id,pos)=>`<div class="order-row"><span>${pos+1}</span><span class="rowtext">${t.items[id]}</span><div class="move"><button data-move="${pos}" data-dir="-1" ${pos===0?'disabled':''} aria-label="${esc(t.items[id])} nach oben">↑</button><button data-move="${pos}" data-dir="1" ${pos===order.length-1?'disabled':''} aria-label="${esc(t.items[id])} nach unten">↓</button></div></div>`).join('');document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.dir);[order[i],order[j]]=[order[j],order[i]];changed();renderInput();document.querySelector(`[data-move="${j}"]:not(:disabled)`)?.focus();});}
 else if(t.type==='mark'){el.innerHTML='<p class="small">Markiere einzelne Wörter per Klick oder Tastatur. Erneutes Anklicken entfernt die Markierung.</p><div class="passage">'+t.passage.map((w,i)=>`<button class="word ${selection.includes(i)?'marked':''}" data-word="${i}" aria-pressed="${selection.includes(i)}">${w}</button>`).join(' ')+'</div>';document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const i=+b.dataset.word;selection=selection.includes(i)?selection.filter(v=>v!==i):[...selection,i];changed();renderInput();document.querySelector(`[data-word="${i}"]`).focus();});}
 else if(t.type==='letters'){el.innerHTML='<p class="small">Setze die Buchstaben zum gesuchten Wort zusammen. Klicke oben auf einen Buchstaben, um ihn zurückzulegen.</p><div class="letter-slots" aria-label="Dein Lösungswort">'+selection.map((id,i)=>`<button class="letter filled" data-remove="${i}" aria-label="${t.letters[id]} zurücklegen">${t.letters[id]}</button>`).join('')+Array.from({length:t.letters.length-selection.length},()=>'<span class="letter empty">·</span>').join('')+'</div><div class="letter-bank">'+t.letters.map((l,i)=>`<button class="letter" data-letter="${i}" ${selection.includes(i)?'disabled':''} aria-label="${l} einsetzen">${l}</button>`).join('')+'</div>';document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{selection.push(+b.dataset.letter);changed();renderInput();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selection.splice(+b.dataset.remove,1);changed();renderInput();});}
 else if(t.type==='sort'||t.type==='pairs'){el.innerHTML=`<p class="small">${t.type==='pairs'?'Wähle links einen Begriff und rechts seine Verbindung. Jede rechte Karte gehört zu genau einem Begriff.':'Wähle eine Fundkarte und lege sie per Klick in die passende Kultur. Du kannst Karten jederzeit neu zuordnen.'}</p><div class="connections"><div class="card-bank">${t.items.map((item,i)=>`<button class="connect-card ${activeCard===i?'selected':''}" data-card="${i}" aria-pressed="${activeCard===i}"><strong>${i+1}. ${item}</strong>${Number.isInteger(selection[i])?`<small>→ ${t.categories[selection[i]]}</small>`:'<small>Noch nicht zugeordnet</small>'}</button>`).join('')}</div><div class="targets">${t.categories.map((c,j)=>`<button class="connect-target" data-target="${j}" ${activeCard===null?'disabled':''}><strong>${c}</strong><small>${t.items.map((_,i)=>selection[i]===j?String(i+1):'').filter(Boolean).join(', ')||'—'}</small></button>`).join('')}</div></div><p class="small" role="status">${activeCard===null?'Wähle zuerst eine Karte.':`Karte ${activeCard+1} gewählt. Wähle jetzt das Ziel.`}</p>`;document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{activeCard=+b.dataset.card;renderInput();document.querySelector('[data-target]')?.focus();});document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{const j=+b.dataset.target;if(t.type==='pairs')selection=selection.map(v=>v===j?null:v);selection[activeCard]=j;activeCard=null;changed();renderInput();});}
}
function complete(correct,self=false){const prev=state.results[key()];state.results[key()]={first:self?false:prev?prev.first:correct,correct:!!prev?.correct||correct};save();sidebar();$('#next').hidden=!state.results[key()].correct;document.querySelector(`[data-task="${state.task}"]`)?.classList.toggle('done',state.results[key()].correct);}
function check(){const t=current();let valid=true,correct=false;
 if(t.type==='write'){valid=t.prompts.every((_,i)=>String(selection[i]||'').trim().length>=12);if(valid){$('#feedback').innerHTML=`<div class="feedback"><strong>Vergleiche und überarbeite deinen Text.</strong><p>${t.why}</p><div class="rubric">${t.criteria.map((c,i)=>`<label><input type="checkbox" data-criterion="${i}">${c}</label>`).join('')}</div><p class="small">Bestätige nur Kriterien, die dein Text tatsächlich erfüllt. Du kannst ihn oben weiterbearbeiten.</p><button class="primary" id="selfDone" disabled>Selbstprüfung abschliessen</button></div>`;document.querySelectorAll('[data-criterion]').forEach(b=>b.onchange=()=>{$('#selfDone').disabled=![...document.querySelectorAll('[data-criterion]')].every(c=>c.checked);});$('#selfDone').onclick=()=>{complete(true,true);$('#selfDone').disabled=true;$('#selfDone').textContent='Selbstprüfung abgeschlossen';};return;}}
 else if(t.type==='text'){valid=t.fields.every((_,i)=>String(selection[i]||'').trim());correct=t.fields.every((f,i)=>f.accept.some(a=>normalize(a)===normalize(selection[i]||'')));}
 else if(t.type==='number'){valid=String(selection[0]||'').trim()!=='';correct=Number(selection[0])===t.answer;}
 else if(t.type==='letters'){valid=selection.length===t.letters.length;correct=selection.map(i=>t.letters[i]).join('')===t.answer;}
 else if(t.type==='order'){correct=JSON.stringify(order)===JSON.stringify(t.answer);}
 else if(t.type==='mark'){valid=selection.length>0;correct=JSON.stringify([...selection].sort((a,b)=>a-b))===JSON.stringify(t.answer);}
 else{valid=t.items.every((_,i)=>Number.isInteger(selection[i]));correct=JSON.stringify(selection)===JSON.stringify(t.answer);}
 if(!valid){$('#feedback').innerHTML=`<p role="status">${t.type==='write'?'Bitte formuliere zu jedem Feld einen kurzen Gedanken (mindestens 12 Zeichen). Das ist nur eine Eingabeprüfung, keine Bewertung.':'Bitte vervollständige zuerst deine Lösung.'}</p>`;return;}
 complete(correct);$('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'Spur entschlüsselt!':'Noch nicht ganz.'}</strong><p>${t.why}</p>${!correct&&t.type==='text'?`<p>Gesuchte Begriffe: ${t.fields.map(f=>f.accept[0]).join(' · ')}</p>`:''}${correct?'':'<p>Überarbeite deine Lösung mit diesem Hinweis und prüfe sie erneut.</p>'}</div>`;$('#check').disabled=true;
}
function next(){if(state.task<2)start(state.station,state.task+1);else if(state.station<5)start(state.station+1);else{showResult=true;render();$('#game').focus();}}
function renderResult(){const points=Object.values(state.results).filter(r=>r.first).length,solved=Object.values(state.results).filter(r=>r.correct).length;
 const missing=stations.flatMap((s,i)=>s.tasks.map((t,j)=>({s:i,t:j,title:s.title,result:state.results[`${i}-${j}`]}))).filter(x=>!x.result?.correct);
 $('#game').innerHTML=`<section class="mission"><div class="eyebrow">DEIN EXPEDITIONSBERICHT</div><h2>${solved===18?'Die Vitrine ist bereit.':'Es gibt noch Spuren zu entdecken.'}</h2><div class="result-number">${solved}<span style="font-size:26px"> / 18</span></div><p>${points} von ${autoCount} automatisch prüfbaren Aufgaben waren Ersttreffer. Offene Texte zählen nach deiner Selbstprüfung als abgeschlossen. ${solved===18?'Du hast alle Aufgaben gelöst. Formuliere jetzt dein eigenes Urteil.':'Kehre zu den offenen Aufgaben zurück.'}</p></section>${missing.length?`<div class="review-list">${missing.map(x=>`<button class="quiet" data-review="${x.s},${x.t}">${x.title} · Spur ${x.t+1} bearbeiten →</button>`).join('')}</div>`:''}<section class="card final-card"><div class="taskmeta">TRANSFER · DEIN EIGENES URTEIL</div><h3>Waren die Kelten «nur wilde Barbaren»?</h3><p>Schreibe eine Museumsbeschriftung in 3–5 Sätzen. Nenne zwei konkrete Belege und eine Grenze unseres Wissens.</p><label for="judgment" class="small">Dein Ausstellungstext · wird nur lokal gespeichert</label><textarea id="judgment" placeholder="Das pauschale Bild greift zu kurz, denn …">${esc(state.draft)}</textarea><details class="rubric"><summary>Selbstcheck und Beispiel</summary><p>Dein Text wird nicht automatisch benotet. Prüfe ihn anhand dieser Kriterien:</p><label><input type="checkbox">Ich nenne mindestens zwei konkrete Belege.</label><label><input type="checkbox">Ich unterscheide Funde, Deutungen und fremde Perspektiven.</label><label><input type="checkbox">Ich vermeide pauschale Aussagen über alle Kelten.</label><p><strong>Mögliche Antwort:</strong> Keltische Gruppen lebten nicht nur vom Krieg. Eisenwerkzeuge und Münzen belegen handwerkliche Spezialisierung und wirtschaftlichen Austausch. Befestigte Siedlungen erfüllten mehrere zentrale Funktionen. Römische und griechische Texte zeigen oft einen Blick von aussen; auch archäologische Funde lassen nicht jede Frage eindeutig beantworten.</p></details><details><summary>Weiterdenken: Erinnerung und «Hochkultur»</summary><p>Die Präsentation erinnert über Asterix an die Kelten. Welche Bilder werden dabei verstärkt? Vergleiche Unterhaltung mit einem Museumsbeitrag.</p><p>Städte, Arbeitsteilung, Kunst und Handel sprechen für eine komplexe Gesellschaft. Fehlende eigene erhaltene Geschichtswerke bedeuten weder fehlenden Schriftgebrauch noch kulturelle Minderwertigkeit. Diskutiert, was der Begriff «Hochkultur» sichtbar macht und welche Wertungen er mitbringt.</p></details><div class="actions"><button class="primary" id="download">Bericht herunterladen</button><button class="quiet" id="print">Drucken</button><button class="quiet" id="again">Stationen wiederholen</button></div></section>`;
 $('#judgment').oninput=e=>{state.draft=e.target.value;save();};$('#print').onclick=()=>window.print();$('#again').onclick=()=>start(0);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>start(...b.dataset.review.split(',').map(Number)));
 $('#download').onclick=()=>{const report=`DIE KELTEN – EXPEDITIONSBERICHT\n\nAbgeschlossen: ${solved}/18\nErsttreffer bei automatisch prüfbaren Aufgaben: ${points}/${autoCount}\n\n${stations.map((s,i)=>s.title+': '+s.tasks.filter((_,j)=>state.results[`${i}-${j}`]?.correct).length+'/3 gelöst').join('\n')}\n\nMEINE AUFGABENTEXTE\n${stations.flatMap((s,i)=>s.tasks.map((t,j)=>t.type==='write'?s.title+' – '+t.q+'\n'+t.prompts.map((p,n)=>p+': '+(state.answers[`${i}-${j}`]?.[n]||'(offen)')).join('\n'):'')).filter(Boolean).join('\n\n')}\n\nMEIN MUSEUMSURTEIL\n${state.draft||'(Noch kein Text verfasst.)'}\n\nGrundlagen: Die Kelten.docx; PPP_Kelten (1).pptx; SRF: Die Kelten und die Römer.\n${SRF}`;const url=URL.createObjectURL(new Blob([report],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Kelten-Expeditionsbericht.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
$('#sourceContent').innerHTML=`<p><strong>Spielregeln:</strong> Entschlüssle 18 Spuren in sechs frei zugänglichen Stationen. Es gibt keine Multiple-Choice-Fragen. Begriffe, Zeitanker, Karten, Paare, Reihenfolgen, Textmarkierungen und Buchstabenrätsel werden automatisch geprüft. Offene Texte schliesst du nach dem Vergleich mit Kriterien selbst ab; sie werden nicht automatisch benotet. Nur automatisch prüfbare Aufgaben zählen für Ersttreffer. Wiederholungen sind unbegrenzt. Wissenskarten stehen jederzeit zur Verfügung. Es gibt keinen Timer.</p><ul><li><strong>Die Kelten.docx:</strong> Sachtext aus Notz/Frey (Hg.), <em>Geschichte fürs Gymnasium. Steinzeit bis 1450</em>, Bern 2024, S. 118–122, und ergänzende Auszüge von Diodor, Caesar und Felix Müller. Die Aufgaben des Dokuments wurden als Lernanregungen behandelt.</li><li><strong>PPP_Kelten (1).pptx:</strong> Einstieg über das Gallierbild und die Behauptung, Kelten seien nur Barbaren (Folien 3–4). Namen aus dem Klassen-Glücksrad und fremde Abbildungen werden nicht veröffentlicht.</li><li><strong><a href="${SRF}" target="_blank" rel="noopener">SRF: Die Kelten und die Römer</a></strong> (2024). Die Videoaufgaben wurden mit den deutschen SRF-Untertiteln abgeglichen. Video und Untertitel verbleiben bei SRF.</li><li><strong>Fachliche Präzisierung:</strong> <a href="https://hls-dhs-dss.ch/de/articles/008016/2007-07-30/" target="_blank" rel="noopener">Historisches Lexikon der Schweiz: Kelten</a> und <a href="https://hls-dhs-dss.ch/de/articles/008015/2014-02-19/" target="_blank" rel="noopener">Latènezeit</a>. Nicht alle keltischen Gruppen der heutigen Schweiz waren Helvetier. Fehlende eigene Geschichtsschreibung ist nicht mit fehlendem Schriftgebrauch gleichzusetzen.</li></ul><p>Alle Aufgaben und Wissenskarten sind neu formuliert. Unsichere Einzelangaben des Ausgangstexts zur Wanderungs- und Eroberungschronologie werden nicht als Quizfakten verwendet. Der Begriff «Hochkultur» wird als Diskussionsfrage behandelt.</p><p><strong>Speicherung:</strong> Das Spiel benötigt kein Konto. Antworten und Ausstellungstext bleiben in diesem Browser. Beim Öffnen des Videos oder externer Links gelten die Bedingungen des jeweiligen Anbieters.</p>`;
$('#sourcesBtn').onclick=()=>$('#sources').showModal();$('#closeSources').onclick=()=>$('#sources').close();
$('#reset').onclick=()=>{if(confirm('Alle Antworten und deinen Ausstellungstext in diesem Browser löschen und neu beginnen?')){state={station:0,task:0,results:{},answers:{},draft:''};start(0);}};
loadAnswer();render();
